import unittest
from importer import import_rows

class ImportTests(unittest.TestCase):
    def test_quoted_comma(self):
        self.assertEqual(import_rows('007,"blue, green"\n'), [{"id":"007", "label":"blue, green"}])
    def test_blank_lines_and_schema(self):
        self.assertEqual(import_rows('007,blue\n\n'), [{"id":"007", "label":"blue"}])
    def test_embedded_newline(self):
        self.assertEqual(import_rows('007,"blue\ngreen"\n'), [{"id":"007", "label":"blue\ngreen"}])
    def test_duplicate_order(self):
        self.assertEqual(import_rows('007,blue\n007,green\n'), [{"id":"007", "label":"blue"}, {"id":"007", "label":"green"}])
